function Platform(x, y, w = PLATFORM_WIDTH, h = PLATFORM_HEIGHT) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.vx = -PLATFORM_SPEED; // move left
    this.update = function () {
      this.x += this.vx;
      // recycle when off screen
      if (this.x + this.w < 0) this.x = W;
    };
    this.draw = function () {
      ctx.fillStyle = '#555';
      ctx.fillRect(this.x, this.y, this.w, this.h);
    };
  }

